/** A demo by id: server HTML, or an island that hydrates when it scrolls into view. */
export function UiDemo(props: { id: string }) {
  switch (props.id) {
    case "checkbox-1":
      return <NewsletterOptIn client:visible />;
    case "checkbox-group-1":
      return <ToppingsGroup />;
    case "combobox-1":
      return <CityField />;
    case "combobox-2":
      return <TagPicker client:visible />;
    case "dialog-1":
      return <DeleteProject />;
    case "dialog-2":
      return <EditProfile client:visible />;
    case "field-1":
      return <EmailField />;
    case "fieldset-1":
      return <AddressFields />;
    case "form-1":
      return <SignupForm client:visible />;
    case "input-1":
      return <BookSearch client:visible />;
    case "installation-1":
      return <Help />;
    case "menu-1":
      return <ProjectMenu />;
    case "menu-2":
      return <EditorMenu client:visible />;
    case "popover-1":
      return <Notifications />;
    case "popover-2":
      return <Filters client:visible />;
    case "radio-group-1":
      return <ShippingChoice client:visible />;
    case "select-1":
      return <PlanField />;
    case "select-2":
      return <ThemePicker client:visible />;
    case "switch-1":
      return <AirplaneMode client:visible />;
    case "tabs-1":
      return <AccountSettings />;
    case "tabs-2":
      return <Project client:visible />;
    case "tooltip-1":
      return <BoldButton />;
    default:
      throw new Error(`No UI demo "${props.id}": run pnpm --filter @lumiose/web ui:demos.`);
  }
}
